import{_ as a,C as i,o as r,c as n,a5 as t,j as d,a as l,E as s}from"./chunks/framework.-jms6n7v.js";const f=JSON.parse('{"title":"커밋과 복구","description":"이 페이지는 쓰기 트랜잭션이 커밋된 상태를 위험에 빠뜨리지 않고 파일을 바꾸는 방법, 커밋이 내구성을 갖는 시점, 크래시나 정전 뒤에 파일을 열 때 일어나는 일을 설명합니다.","frontmatter":{"title":"커밋과 복구","order":4,"prev":{"text":"파일 형식","link":"/ko/engine/file-format"},"next":{"text":"잠금","link":"/ko/engine/locking"}},"headers":[{"level":2,"title":"엔진이 가정하는 것","slug":"엔진이-가정하는-것","link":"#엔진이-가정하는-것","children":[]},{"level":2,"title":"쓰기 시 복사","slug":"쓰기-시-복사","link":"#쓰기-시-복사","children":[]},{"level":2,"title":"다시 써도 되는 페이지","slug":"다시-써도-되는-페이지","link":"#다시-써도-되는-페이지","children":[]},{"level":2,"title":"동기 커밋","slug":"동기-커밋","link":"#동기-커밋","children":[]},{"level":2,"title":"지연 커밋","slug":"지연-커밋","link":"#지연-커밋","children":[]},{"level":2,"title":"크래시가 되돌릴 수 있는 것","slug":"크래시가-되돌릴-수-있는-것","link":"#크래시가-되돌릴-수-있는-것","children":[]},{"level":2,"title":"슬롯 고르기","slug":"슬롯-고르기","link":"#슬롯-고르기","children":[]},{"level":2,"title":"동기화가 실패하면","slug":"동기화가-실패하면","link":"#동기화가-실패하면","children":[]},{"level":2,"title":"복구","slug":"복구","link":"#복구","children":[]},{"level":2,"title":"데이터베이스 만들기","slug":"데이터베이스-만들기","link":"#데이터베이스-만들기","children":[]}],"relativePath":"ko/engine/commits-and-recovery.md","filePath":"ko/engine/commits-and-recovery.md","lastUpdated":1791623047000}'),c={name:"ko/engine/commits-and-recovery.md"};function h(p,e,u,g,m,_){const o=i("LangCode");return r(),n("div",null,[e[2]||(e[2]=t('<h1 id="커밋과-복구" tabindex="-1">커밋과 복구 <a class="header-anchor" href="#커밋과-복구" aria-label="Permalink to &quot;커밋과 복구&quot;">​</a></h1><p>이 페이지는 쓰기 트랜잭션이 커밋된 상태를 위험에 빠뜨리지 않고 파일을 바꾸는 방법, 커밋이 내구성을 갖는 시점, 크래시나 정전 뒤에 파일을 열 때 일어나는 일을 설명합니다.</p><p>명세는 저장소의 <a href="https://github.com/jooy2/darudb/blob/main/design/commits-and-recovery.md" target="_blank" rel="noreferrer">design/commits-and-recovery.md</a>에 있습니다. 쓰는 방법은 <a href="./../guide/transactions">트랜잭션</a>에서 다룹니다.</p><h2 id="엔진이-가정하는-것" tabindex="-1">엔진이 가정하는 것 <a class="header-anchor" href="#엔진이-가정하는-것" aria-label="Permalink to &quot;엔진이 가정하는 것&quot;">​</a></h2><p>아래 내용은 플랫폼이 다섯 가지 약속을 지킬 때 성립하며, 엔진은 이 밖에 아무것도 기대하지 않습니다. 이 페이지에서 동기화는 파일에 쓴 내용이 디스크에 닿을 때까지 기다리는 호출 한 번을 뜻합니다.</p><ol><li><strong>1바이트 쓰기는 원자적입니다.</strong> 정전이 나도, 쓰던 바이트는 옛 값과 새 값 중 하나를 갖습니다.</li><li><strong>쓰기는 지정한 바이트만 바꿉니다.</strong> 다른 바이트와 섹터를 공유하든 그렇지 않든 마찬가지입니다.</li><li><strong>동기화는 확실합니다.</strong> 파일 동기화가 성공해 반환되면, 그 전에 한 쓰기는 모두 내구성을 갖습니다. 엔진은 Linux, Android와 BSD 계열에서는 <code>fdatasync</code>를, macOS와 iOS에서는 <code>F_FULLFSYNC</code>를, Windows에서는 <code>FlushFileBuffers</code>를 씁니다. <code>fdatasync</code>는 데이터와 함께 파일 길이를 영속시키고, 아무도 읽지 않는 파일 시각은 빼놓습니다. macOS와 iOS의 평범한 <code>fsync</code>는 드라이브 캐시까지만 닿기 때문에 <code>F_FULLFSYNC</code>를 씁니다.</li><li><strong>바이트 범위 잠금이 동작하고, 잠금을 쥔 프로세스가 끝나면 함께 풀립니다.</strong></li><li><strong>파일 시스템은 로컬입니다.</strong> 네트워크 파일 시스템은 3번과 4번 약속을 어기므로, 엔진은 그런 곳에 있는 데이터베이스를 열지 않습니다.</li></ol><p>두 동기화 사이의 쓰기는 어떤 순서로든 디스크에 닿을 수 있고, 정전으로 중간에 끊긴 쓰기는 그 범위에 옛 바이트와 새 바이트를 아무렇게나 섞어 남길 수 있습니다. 디스크에 있는 동안 페이지가 손상될 수도 있습니다. 둘 다 페이지마다 있는 검사값이 잡아냅니다.</p><h2 id="쓰기-시-복사" tabindex="-1">쓰기 시 복사 <a class="header-anchor" href="#쓰기-시-복사" aria-label="Permalink to &quot;쓰기 시 복사&quot;">​</a></h2><p>커밋된 페이지는 절대 바꾸지 않습니다. 항목 하나를 바꿀 때 쓰는 쪽은 그 항목이 든 리프의 새 사본을 빈 페이지에 쓰고, 그 사본을 가리키는 부모의 새 사본을 쓰고, 이렇게 루트까지 올라갑니다. 새 커밋 레코드는 새 루트를 가리킵니다. 이 레코드가 게시되기 전에는 아무것도 새 페이지에 닿지 않으므로, 그 전에 언제 크래시가 나든 마지막 커밋은 그대로 남고, 트랜잭션을 취소할 때 되돌릴 것도 없습니다.</p><p>한 트랜잭션 안에서 커밋된 페이지를 복사하는 것은 처음 바꿀 때 한 번뿐이고, 그 뒤의 변경은 메모리에 있는 사본에 합니다. 큰 값은 넣는 즉시 따로 차지한 페이지에 쓰지만, 그 페이지는 커밋이 가리키기 전까지 아무것도 닿지 않는 빈 자리에 있습니다.</p><h2 id="다시-써도-되는-페이지" tabindex="-1">다시 써도 되는 페이지 <a class="header-anchor" href="#다시-써도-되는-페이지" aria-label="Permalink to &quot;다시 써도 되는 페이지&quot;">​</a></h2><p>한 커밋을 기준으로 파일의 모든 페이지는 세 상태 중 정확히 하나에 있고, 엔진의 빈 페이지 트리와 보류 트리가 이를 기록합니다.</p><ul><li><strong>사용 중</strong>: 그 커밋이 닿는 페이지입니다.</li><li><strong>보류</strong>: 이전 커밋만 닿는 페이지입니다. 읽는 쪽이나 복구가 아직 그 커밋을 필요로 할 수 있습니다. 보류 페이지는 더는 쓰지 않게 된 커밋별로 묶어 둡니다.</li><li><strong>빈 페이지</strong>: 앞으로 읽힐 수 있는 무엇도 닿지 않는 페이지입니다. 새로 쓰는 것은 이 페이지뿐입니다.</li></ul><p>쓰기 트랜잭션은 시작할 때, 어느 프로세스의 읽기 트랜잭션도, 일어날 수 있는 어떤 복구도 더는 닿지 않는 보류 묶음을 모두 빈 페이지로 돌립니다. 그래서 읽기 트랜잭션은 살아 있는 동안 자기 커밋의 페이지를 붙잡아 두고, 그동안 다른 쪽이 쓰면 파일이 커집니다. 하지만 쓰는 쪽을 기다리게 하지는 않습니다. 지연 커밋이 썼다가 곧 쓰지 않게 된 페이지는 필요한 읽기가 없어지는 즉시 더 일찍 돌려받습니다. 그래서 같은 객체를 바꾸는 작은 지연 커밋이 이어져도 파일이 커지지 않고 같은 페이지를 거듭 씁니다.</p><p>쓰는 쪽은 번호가 낮은 빈 페이지부터 가져다 쓰므로 파일 앞쪽이 촘촘하게 유지되고, 동기 커밋은 파일 끝에 있는 빈 페이지를 파일 시스템에 돌려줍니다. 더 많이 돌려주려면 <a href="./../guide/tools">압축</a>으로 덜 찬 트리의 페이지를 채우고 페이지를 앞으로 옮깁니다.</p><h2 id="동기-커밋" tabindex="-1">동기 커밋 <a class="header-anchor" href="#동기-커밋" aria-label="Permalink to &quot;동기 커밋&quot;">​</a></h2><p>동기 커밋은 반환될 때 이미 내구성을 갖습니다. Rust에서는 <code>commit</code>이고, Node.js와 Dart, Python에서는 쓰기의 기본 내구성입니다. 동기화는 한 번 합니다.</p><ol><li>트랜잭션이 바꾼 페이지를 모두 씁니다. 이어진 페이지 묶음은 호출 한 번으로 씁니다.</li><li>아무도 필요로 하지 않는 슬롯에 커밋 레코드를 씁니다.</li><li><strong>동기화.</strong> 여기가 커밋 시점입니다. 이제부터 커밋은 정전에도 살아남습니다.</li><li>새 슬롯을 가리키도록 선택 바이트를 씁니다. 커밋이 게시되고, 새로 시작하는 읽기가 이 커밋을 봅니다.</li><li>파일 끝의 빈 페이지를 잘라 냅니다.</li></ol><p>선택 바이트를 쓴 뒤에는 동기화를 다시 하지 않습니다. 정전으로 그 1바이트 쓰기를 잃으면, 복구가 게시된 것보다 새 레코드를 찾아 검사한 뒤 게시합니다. 그리고 선택 바이트는 동기화가 끝난 뒤에야 쓰므로, 정전으로 되돌려질 수 있는 동기 커밋을 읽는 쪽이 보는 일은 없습니다.</p><h2 id="지연-커밋" tabindex="-1">지연 커밋 <a class="header-anchor" href="#지연-커밋" aria-label="Permalink to &quot;지연 커밋&quot;">​</a></h2>',20)),d("p",null,[e[0]||(e[0]=l("지연 커밋은 ",-1)),s(o,{rust:"commit_deferred",node:"durability: 'deferred'",dart:"Durability.deferred",python:'durability="deferred"'}),e[1]||(e[1]=l("입니다. 페이지와 레코드를 쓰고 곧바로 게시하되, 동기화 없이 선택 바이트의 미동기화 비트를 켭니다. 반환되는 즉시 읽는 쪽에 보입니다. 마지막 동기화 이후의 지연 커밋을 미동기화 구간이라 부르며, 다음 일이 일어나면 동기화로 구간이 끝납니다.",-1))]),e[3]||(e[3]=t('<ul><li><strong>다음 동기 커밋.</strong> 그 커밋의 동기화가 구간 전체를 덮습니다.</li><li><strong><code>sync</code> 호출, 또는 데이터베이스 닫기.</strong> 닫기는 <code>sync</code>를 부릅니다. 프로세스에서 파일의 마지막 핸들을 닫지 않고 버려도 같은 일이 일어나지만, 실패를 알릴 방법은 없습니다.</li><li><strong>페이지 제한.</strong> 구간을 16,384페이지 넘게 만들 지연 커밋은 동기 커밋으로 바뀝니다. 같은 페이지는 구간에서 몇 번을 쓰든 한 번으로 셉니다.</li><li><strong>시간 제한.</strong> 구간이 1초 동안 열려 있으면 <code>darudb-sync</code> 스레드가 실행 중인 쓰기 트랜잭션이 끝나기를 기다려 동기화합니다. 시간이 지난 뒤에 하는 지연 커밋도 동기 커밋으로 바뀝니다. 스레드가 돌지 못한 경우에도 구간이 끝나게 하려는 장치입니다.</li><li><strong>다른 프로세스.</strong> 죽은 프로세스는 자기 구간을 열어 둔 채 남깁니다. 자기 구간이 없는 프로세스가 읽기 트랜잭션을 시작하거나 파일을 열다가 게시된 커밋이 동기화되지 않은 것을 보면, 그 구간이 열린 지 자기 시간 제한보다 오래됐을 때 구간을 끝냅니다. 파일을 열어 두기만 하고 읽지도 쓰지도 다시 열지도 않는 프로세스는 알아채지 못합니다.</li></ul><p>제한은 프로세스마다가 아니라 구간 전체에 걸립니다. 지연 커밋의 레코드에는 구간이 언제 열렸고 지금까지 페이지를 몇 개 썼는지가 적혀 있어서, 다른 프로세스 다음에 지연 커밋을 하는 프로세스는 거기서부터 이어 셉니다. 프로세스마다 제한을 다르게 두면 구간은 그중 가장 엄격한 제한에서 끝납니다. 다른 프로세스가 어느 페이지를 썼는지는 알 수 없으므로, 다른 프로세스가 쓴 페이지를 다시 쓰면 두 번 셉니다. 동기화가 조금 일찍 올 뿐입니다. 열린 시각은 시스템 시계로 적습니다. 시계를 뒤로 돌려 지금보다 늦은 시각이 적혀 있는 것처럼 프로세스가 믿을 수 없는 시각이면, 구간이 이미 시간 제한을 넘긴 것으로 봅니다.</p><p>Rust에서는 <code>OpenOptions::max_unsynced_pages</code>와 <code>OpenOptions::max_unsynced_time</code>으로 제한을 바꿀 수 있고, Node.js와 Dart, Python 패키지는 기본값을 씁니다. 페이지 제한은 구간을 끝내는 동기화가 써야 할 양과 정전 뒤에 복구가 검사할 양을 묶어 두고, 시간 제한은 정전이 되돌릴 수 있는 양을 묶어 둡니다.</p><p>지연 커밋은 커밋마다 디스크를 기다리느니 정전 때 마지막 몇 커밋을 잃는 편을 택하는 애플리케이션을 위한 것입니다.</p><h2 id="크래시가-되돌릴-수-있는-것" tabindex="-1">크래시가 되돌릴 수 있는 것 <a class="header-anchor" href="#크래시가-되돌릴-수-있는-것" aria-label="Permalink to &quot;크래시가 되돌릴 수 있는 것&quot;">​</a></h2><table tabindex="0"><thead><tr><th>일어난 일</th><th>동기 커밋</th><th>지연 커밋</th></tr></thead><tbody><tr><td>프로세스가 비정상 종료되거나 강제 종료됨</td><td>잃는 것 없음</td><td>잃는 것 없음. 프로세스가 쓴 내용은 운영체제가 모두 갖고 있습니다</td></tr><tr><td>정전</td><td>반환된 커밋은 잃지 않음</td><td>가장 최근 것부터 되돌려질 수 있고, 중간이 빠지지는 않음</td></tr></tbody></table><p>어느 경우든 파일에는 커밋이 통째로 남고 일부만 남는 일은 없으며, 남는 커밋은 마지막으로 반환된 동기 커밋보다 오래되지 않습니다. 정전이 파일을 망가뜨리지도 않습니다.</p><h2 id="슬롯-고르기" tabindex="-1">슬롯 고르기 <a class="header-anchor" href="#슬롯-고르기" aria-label="Permalink to &quot;슬롯 고르기&quot;">​</a></h2><p>새 레코드는 읽는 쪽이나 복구가 아직 필요로 할 수 있는 레코드를 덮어쓰지 않습니다. 게시된 커밋, 내구성이 보장된 커밋, 그리고 정전이 나면 복구가 검사 없이 믿을 커밋이 그렇습니다. 파일을 연 직후나 다른 프로세스가 커밋한 뒤처럼 마지막 것이 어느 커밋인지 알 수 없을 때는 대신 레코드 하나를 더 남겨 둡니다. 남은 슬롯 가운데서는 게시하기 전에 죽은 쓰는 쪽이 남긴 슬롯을 먼저 고르고, 없으면 가장 오래된 슬롯을 고릅니다.</p><p>남은 슬롯이 없으면 커밋은 레코드를 쓰기 전에 동기화를 한 번 합니다. 그러면 지켜야 할 것은 게시된 커밋과 내구성이 보장된 커밋뿐이게 됩니다. 이 추가 동기화는 구간 없이 한 동기 커밋 다음의 두 번째 지연 커밋에서, 그리고 다른 프로세스가 구간의 첫 지연 커밋을 한 뒤 쓰는 쪽의 첫 커밋에서 일어납니다.</p><h2 id="동기화가-실패하면" tabindex="-1">동기화가 실패하면 <a class="header-anchor" href="#동기화가-실패하면" aria-label="Permalink to &quot;동기화가 실패하면&quot;">​</a></h2><p>동기화가 실패하면 운영체제가 쓰지 못한 페이지를 이미 버리고 깨끗한 것으로 표시했을 수 있습니다. 그러면 다시 시도했을 때 실제로는 일어나지 않은 성공을 보고할 수 있습니다. 그래서 엔진은 다시 시도하지 않습니다.</p><ul><li>커밋은 <code>SYNC_FAILED</code>로 실패하고, 결과는 알 수 없습니다. 나중에 복구가 그 커밋을 찾아 게시할 수도 있습니다.</li><li>그 뒤로 이 프로세스에서 그 파일에 하는 호출은 모두 <code>SYNC_FAILED</code>로 실패합니다. 그 파일의 핸들을 모두 닫고 다시 열어야 디스크에 있는 내용에서 새로 시작합니다. 핸들을 닫을 때가 실패한 동기화를 알 수 있는 마지막 기회입니다.</li><li>다른 프로세스는 영향을 받지 않습니다. 동기 커밋은 동기화가 성공한 뒤에야 게시되므로 다른 프로세스는 그 커밋을 본 적이 없습니다.</li></ul><h2 id="복구" tabindex="-1">복구 <a class="header-anchor" href="#복구" aria-label="Permalink to &quot;복구&quot;">​</a></h2><p>복구는 파일을 연 다른 프로세스가 없을 때, 파일을 처음 여는 프로세스에서 일어납니다. 다른 프로세스가 있는지는 열기 잠금으로 압니다(<a href="./locking">잠금</a>). 마지막 프로세스가 파일을 정상적으로 닫았다면 복구에는 헤더를 한 번 읽는 비용만 듭니다.</p><ol><li>커밋 레코드 세 개를 읽고, 유효하면서 페이지 수가 파일에 들어맞는 것만 남깁니다. 파일보다 많은 페이지를 센 레코드는, 그 레코드보다 먼저 한 쓰기 일부가 살아남지 못했다는 뜻입니다. 암호화한 파일에서는 MAC이 맞지 않는 레코드도 유효하지 않습니다.</li><li>트랜잭션 ID가 큰 것부터 차례로 보면서, 미동기화 비트가 꺼진 게시된 커밋이거나 검사를 통과한 레코드를 처음 만나면 그것을 택합니다. 미동기화 비트가 꺼진 게시된 커밋은 내구성이 보장된 것으로 압니다.</li><li>택한 커밋이 게시된 커밋이 아니거나, 미동기화 비트가 켜져 있었거나, 더 새 레코드가 남아 있으면, 더 새 레코드를 지우고 택한 커밋을 미동기화 비트를 끈 채 게시합니다. 이때 앞뒤로 동기화를 한 번씩 합니다.</li><li>파일을 택한 커밋의 페이지 수에 맞게 자릅니다.</li></ol><p><strong>커밋을 검사할 때</strong>는 그 커밋이 닿는 페이지 가운데, 레코드에 적힌 내구성이 보장된 커밋보다 나중에 쓴 페이지만 읽습니다. 어느 페이지가 그런지는 포인터의 트랜잭션 ID가 알려 주므로 나머지는 읽지 않습니다. 동기 커밋이라면 그 커밋 하나가 쓴 페이지이고, 지연 커밋 뒤라면 구간이 쓴 페이지입니다. 그 페이지가 모두 온전해야 합니다.</p><p>복구는 반드시 커밋 하나를 찾습니다. 내구성이 보장된 커밋은 늘 조건을 만족하기 때문입니다. 그 커밋의 슬롯은 새 레코드에 쓰이지 않고, 그 커밋의 페이지는 다시 쓰이지 않으며, 그 커밋이 닿는 것은 모두 게시되기 전에 이미 내구성을 가졌습니다. 조건을 만족하는 레코드가 하나도 없다면 파일이 복구로 고칠 수 있는 수준을 넘어 손상된 것이고, 파일 열기는 <code>CORRUPTED</code>로 실패합니다. 그런 파일에는 <a href="./../guide/tools">되살리기</a>를 씁니다.</p><h2 id="데이터베이스-만들기" tabindex="-1">데이터베이스 만들기 <a class="header-anchor" href="#데이터베이스-만들기" aria-label="Permalink to &quot;데이터베이스 만들기&quot;">​</a></h2><p>새 데이터베이스는 먼저 같은 디렉터리의 임시 파일에 통째로 쓰고 동기화합니다. 임시 파일 이름은 데이터베이스 이름 뒤에 무작위 접미사를 붙인 것입니다. 그다음 기존 파일을 덮어쓰지 않고 제 이름으로 옮깁니다. 이름에 링크를 거는데, 이름이 이미 있으면 링크가 실패합니다. 링크가 없는 파일 시스템에서는 플랫폼이 제공하는, 덮어쓰지 않는 이름 바꾸기를 씁니다. 유닉스 계열에서는 디렉터리도 동기화해서 새 이름이 정전에도 남게 합니다.</p><p>그래서 그 경로에는 아무것도 없거나 온전한 데이터베이스가 있을 뿐이고, 두 프로세스가 같은 데이터베이스를 동시에 만들어도 충돌하지 않습니다. 두 번째 프로세스는 첫 프로세스가 만든 파일을 찾아 엽니다. 길이가 0인 파일은 데이터베이스가 아니므로 <code>NOT_A_DATABASE</code>로 거부합니다. 크래시로 남은 임시 파일은 엔진이 읽지 않으므로 지워도 됩니다.</p><p>링크도 덮어쓰지 않는 이름 바꾸기도 없는 파일 시스템에서는 파일을 그 자리에 만들고, 열기 잠금을 혼자 쥔 채 첫 페이지를 씁니다. 그 사이에 크래시가 나면 빈 파일이 남으며, 이 파일은 직접 지워야 합니다.</p>',22))])}const k=a(c,[["render",h]]);export{f as __pageData,k as default};
